using Unity.Entities;
using UnityEngine;

public struct Gun : IComponentData { public Entity Bullet; public float Cooldown; }

// authoring: a MonoBehaviour on a GameObject inside a subscene
public class GunAuthoring : MonoBehaviour
{
    public GameObject bulletPrefab;
    public float cooldown = 0.2f;

    class Baker : Baker<GunAuthoring>
    {
        public override void Bake(GunAuthoring authoring)
        {
            Entity e = GetEntity(TransformUsageFlags.Dynamic);     // it moves
            AddComponent(e, new Gun
            {
                Bullet = GetEntity(authoring.bulletPrefab, TransformUsageFlags.Dynamic),
                Cooldown = authoring.cooldown
            });
        }
    }
}

// GetEntity(TransformUsageFlags.None)       data only, no transform
// GetEntity(TransformUsageFlags.Renderable) drawn, never moves
// GetEntity(TransformUsageFlags.Dynamic)    moves at runtime: LocalTransform

