using Unity.Entities;
using UnityEngine;

public struct Speed : IComponentData { public float Value; }

public class SpeedAuthoring : MonoBehaviour
{
    public float metersPerSecond = 5f;

    class Baker : Baker<SpeedAuthoring>
    {
        public override void Bake(SpeedAuthoring authoring)
        {
            Entity e = GetEntity(TransformUsageFlags.Dynamic); // it moves at runtime
            AddComponent(e, new Speed { Value = authoring.metersPerSecond });
        }
    }
}

