// a regular GameObject (camera rig, UI marker) that follows one entity
public class FollowEntity : MonoBehaviour
{
    public Entity target;   // set by whoever spawned it

    void LateUpdate()
    {
        var em = World.DefaultGameObjectInjectionWorld.EntityManager;
        if (!em.Exists(target)) return;
        // waits for jobs that are writing LocalTransform, so read it late
        transform.position = em.GetComponentData<LocalTransform>(target).Position;
    }
}

// old tutorials (Entities 0.x)            Entities 1.x
// Translation, Rotation, NonUniformScale  LocalTransform
// IConvertGameObjectToEntity              Baker<T> on an authoring MonoBehaviour
// [GenerateAuthoringComponent]            authoring class + a hand-written Baker
// Entities.ForEach in SystemBase          IJobEntity, SystemAPI.Query in ISystem

// the light path: one hot loop, no Entities
public class PathManager : MonoBehaviour
{
    NativeArray<float3> positions;   // Persistent, filled from the 200 objects
    JobHandle handle;

    void Update()
    {
        handle = new PathJob { positions = positions }.Schedule(positions.Length, 16);
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate()
    {
        handle.Complete();
        // copy the results back to the GameObjects
    }
}
